xql_query:
// ============================================================
// Rule: Multiplas alterações de credenciais
// Vendor: Windows
// Objective:
// Detect activity associated with Multiplas alterações de credenciais.
// Severity: SEV_040_HIGH
// Category: CREDENTIAL_ACCESS
// ============================================================

dataset = xdr_data
| filter action_evtlog_event_id = 4724
| fields _time, agent_hostname, action_evtlog_username, action_evtlog_message
| limit 100
